        CONSTRAINT CK_ProductGalleryImages_DisplayOrder CHECK (DisplayOrder >= 1),
        CONSTRAINT UQ_ProductGalleryImages_Product_DisplayOrder UNIQUE (ProductId, DisplayOrder)
    );
END;
