ALTER PROCEDURE dbo.sp_GetFaqs
    @ProductId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        Id,
        ProductId,
        Question,
        Answer,
        DisplayOrder,
        IsActive,
        CreatedAt
    FROM dbo.Faqs
    WHERE IsActive = 1
      AND (@ProductId IS NULL AND ProductId IS NULL
           OR @ProductId IS NOT NULL AND (ProductId IS NULL OR ProductId = @ProductId))
    ORDER BY
        CASE WHEN ProductId IS NULL THEN 0 ELSE 1 END ASC,
        DisplayOrder ASC,
        Id ASC;
END;
GO


