IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.Products') AND name = N'DiscountStartDate')
BEGIN
    ALTER TABLE dbo.Products ADD DiscountStartDate DATETIME2 NULL;
END;
