IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.Products') AND name = N'DiscountEndDate')
BEGIN
    ALTER TABLE dbo.Products ADD DiscountEndDate DATETIME2 NULL;
END;
