-- =====================================================================================
-- 19_user_profile_and_tracking_migration.sql
-- Helmet Cartel Ordering and Management System
-- User Profile Management, Order Tracking, Payment History & Digital Receipts
-- =====================================================================================

SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

