-- 4. Update Stored Procedure: dbo.sp_SaveUserAddress
IF OBJECT_ID(N'dbo.sp_SaveUserAddress', N'P') IS NULL
    EXEC(N'CREATE PROCEDURE dbo.sp_SaveUserAddress AS BEGIN RETURN 0; END');
